create table if not exists public.budget_departments (
  id bigserial primary key, doc_id text not null, doc_title text not null, fiscal_year int not null,
  code text not null, name text not null, page int, source_url text,
  prior_adopted bigint, dept_request bigint, recommended bigint, change bigint, payroll bigint, non_payroll bigint);
alter table public.budget_departments enable row level security;
drop policy if exists "public read budget_departments" on public.budget_departments;
create policy "public read budget_departments" on public.budget_departments for select to public using (true);
truncate public.budget_departments;
